    "study_type": {
      "value": "in_vivo",
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00030",
          "quote": "To explore whether ELF-MF exposure influences cognitive ability and/or hyperphosphorylated tau levels in AD, transgenic mice (3xTg) were used that express an APP/PS1 mutation combined with a tau (P301L) mutation (Oddo et al., 2003)."
        }
      ]
    },
    "study_design": {
      "value": "randomized_controlled_trial",
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00036",
          "quote": "The 3-month-old animals were randomly divided into the following groups: N-Tg-SE (N-Tg mice that were exposed only to the standard environment), N-Tg-MF (N-Tg mice that were exposed to ELF-MF), 3xTg-SE (3xTg mice that were exposed only to the standard environment), and 3xTg-MF (3xTg mice that were exposed to ELF-MF), with a total of six to ten mice per group."
        }
      ]
    },
    "hypothesis": {
      "value": "ELF-MF exposure ameliorates cognitive deficits and increases synaptic proteins in 3xTg mice.",
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00011",
          "quote": "Therefore, transgenic mice (3xTg) were used in the present study. 3xTg mice, which express an APP/PS1 mutation combined with a tau (P301L) mutation and that develop cognitive deficits at 6 months of age, were subjected to ELF-MF (50 Hz, 500 m T) exposure or sham exposure daily for 3 months. We discovered that ELF-MF exposure ameliorated cognitive deficits and increased synaptic proteins in 3xTg mice."
        }
      ]
    },
    "primary_outcome": {
      "value": "amelioration of cognitive deficits and increase in synaptic proteins",
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00011",
          "quote": "We discovered that ELF-MF exposure ameliorated cognitive deficits and increased synaptic proteins in 3xTg mice."
        }
      ]
    },
    "secondary_outcomes": {
      "value": ["decrease in hyperphosphorylated tau levels", "inhibition of apoptosis", "decrease in oxidative stress"],
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00011",
          "quote": "The protective effects of ELF-MF exposure may have also been caused by the inhibition of apoptosis and/or decreased oxidative stress levels that were observed in the hippocampus tissues of treated mice."
        },
        {
          "block_id": "b00104",
          "quote": "Additionally, both the N-Tg-MF and 3xTg-MF groups showed decreased levels of hyperphosphorylated tau at the examined phosphorylation sites."
        },
        {
          "block_id": "b00096",
          "quote": "In our study, oxidative stress levels were measured in the hippocampus of each animal group by using an immunofluorescent assay."
        }
      ]
    },
